<script setup lang="ts">
import {useWorkModeText} from '../workMode'
const {w}=useWorkModeText()
import {onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {addDays,storeToday,hours} from '../time'
import type {Attendance,Option,ScheduleResult} from '../types'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),requestedDate=typeof route.query.date==='string'?route.query.date:'',requestedFrom=typeof route.query.from==='string'?route.query.from:'',requestedTo=typeof route.query.to==='string'?route.query.to:'', {api,home,t,p,base,loading,failure,load,format}=usePhasePage(),from=ref(requestedDate||requestedFrom||addDays(storeToday(),-6)),to=ref(requestedDate||requestedTo||storeToday()),employee=ref(''),employees=ref<Option[]>([]),items=ref<Attendance[]>([]),offset=ref(0),zone=ref('Asia/Singapore');let initial=true
function refresh(reset=true){if(reset)offset.value=0;const span=(Date.parse(to.value)-Date.parse(from.value))/86400000;if(!(span>=0&&span<=30)){failure.value=p('invalid');return}void load(async()=>{const [r,s]=await Promise.all([api().get<{items:Attendance[]}>(`/attendance?from=${from.value}&to=${to.value}&limit=50&offset=${offset.value}${home.value?.employeeManage&&employee.value?'&employeeId='+encodeURIComponent(employee.value):''}`),api().get<ScheduleResult>(`/schedule?from=${from.value}&to=${to.value}`)]);return {r,s}},({r,s})=>{items.value=r.items;if(s){employees.value=s.employees;zone.value=s.timezone}else if(r.items[0])zone.value=r.items[0].schedule.timezone;if(initial){initial=false;if(requestedDate||requestedFrom||requestedTo)return;const actual=storeToday(zone.value);if(actual!==to.value){to.value=actual;from.value=addDays(actual,-6);refresh()}}})}
function page(n:number){offset.value=Math.max(0,offset.value+n);refresh(false)}
onMounted(()=>refresh())
</script>
<template><section class="wf-panel"><nav v-if="home?.employeeManage" class="wf-subnav"><RouterLink :to="base+'/attendance'">{{p('attendance')}}</RouterLink><RouterLink :to="base+'/corrections'">{{p('corrections')}}</RouterLink></nav><h2>{{p(home?.employeeManage?'attendance':'myAttendance')}}</h2><form class="wf-filters" @submit.prevent="refresh()"><label>{{p('from')}}<input v-model="from" type="date" required></label><label>{{p('to')}}<input v-model="to" type="date" :min="from" :max="addDays(from,30)" required></label><label v-if="home?.employeeManage">{{p('employee')}}<select v-model="employee"><option value="">{{p('all')}}</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><button :disabled="loading">{{p('filter')}}</button></form><PhaseStatus :failure="failure" :loading="loading"/><div v-if="!loading" class="wf-table-wrap"><table><thead><tr><th>{{p('workDate')}}</th><th>{{p('employee')}}</th><th>{{p('plan')}}</th><th>{{p('actual')}}</th><th>{{p('breakHours')}}</th><th>{{p('workHours')}}</th><th>{{p('anomalies')}}</th><th></th></tr></thead><tbody><tr v-for="a in items" :key="a.schedule.id"><td>{{a.schedule.workDate}}</td><td>{{a.schedule.employeeName}}<br><small>{{a.schedule.employeeNo}}</small></td><td>{{a.schedule.shift.name}}<br><small>{{format(a.schedule.startAt,a.schedule.timezone)}} – {{format(a.schedule.endAt,a.schedule.timezone)}}</small></td><td>{{format(a.session?.inAt,a.schedule.timezone)}} – {{format(a.session?.outAt,a.schedule.timezone)}}<br><small>{{a.session&&!a.session.outAt?p(a.session.breakStartedAt?'resting':'working'):''}}</small></td><td>{{hours(a.breakSeconds)}}</td><td>{{hours(a.workSeconds)}}</td><td><span v-if="a.exempt" class="wf-badge">{{w('exempt')}}</span><span v-for="anomaly in a.anomalies" :key="anomaly" class="wf-badge">{{p(anomaly as 'OPEN')}}</span><span v-if="a.schedule.status==='cancelled'" class="wf-badge">{{p('cancelled')}}</span></td><td><RouterLink :to="base+'/attendance/'+a.schedule.id">{{p('detail')}}</RouterLink></td></tr><tr v-if="!items.length"><td colspan="8" class="wf-empty">{{t('empty')}}</td></tr></tbody></table></div><footer class="wf-pagination"><button :disabled="loading||offset===0" @click="page(-50)">{{t('previous')}}</button><button :disabled="loading||items.length<50" @click="page(50)">{{t('next')}}</button></footer><p class="wf-hint">{{p('timezone')}}: {{zone}} · {{p('factsHint')}}</p></section></template>

